1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	const sumBy = <T>(items: readonly T[], value: (item: T) => number): number =>
24	  items.reduce((total, item) => total + value(item), 0);
25	
26	interface Item {
27	  type: string;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	}
32	
33	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
34	
35	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
36	
37	const isCursed = (item: Item): boolean => item.cursed === true;
38	const hasHighEnchantmentForPremium = (item: Item): boolean =>
39	  enchantmentOf(item) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD;
40	
41	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
42	  { applies: isCursed, rate: 0.5 },
43	  { applies: hasHighEnchantmentForPremium, rate: 0.3 },
44	];
45	
46	const itemSurcharge = (item: Item): number =>
47	  basePremiumOf(item.type) *
48	  sumBy(SURCHARGE_RATES, ({ applies, rate }) => (applies(item) ? rate : 0));
49	
50	const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);
51	
52	interface QuoteStep {
53	  op: "quote";
54	  items: Item[];
55	}
56	
57	interface Damage {
58	  itemType: string;
59	  amount: number;
60	}
61	
62	interface ClaimStep {
63	  op: "claim";
64	  policy: number;
65	  incident: {
66	    cause: string;
67	    damages: Damage[];
68	  };
69	}
70	
71	type Step = QuoteStep | ClaimStep;
72	
73	interface Customer {
74	  yearsWithMHPCO: number;
75	}
76	
77	interface Scenario {
78	  customer: Customer;
79	  steps: Step[];
80	}
81	
82	interface QuoteResult {
83	  premium: number;
84	}
85	
86	interface ClaimResult {
87	  payout: number;
88	  remainingCap: number;
89	}
90	
91	type StepResult = QuoteResult | ClaimResult;
92	
93	interface ScenarioResult {
94	  results: StepResult[];
95	}
96	
97	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
98	const COMPONENT_BLOCK_SIZE = 3;
99	const COMPONENT_BLOCK_BASE = 60;
100	
101	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
102	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
103	
104	const countItemsByType = (items: Item[]): Array<[string, number]> => {
105	  const counts = new Map<string, number>();
106	  for (const item of items) {
107	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
108	  }
109	  return [...counts];
110	};
111	
112	const isComponentBlock = (type: string, count: number): boolean =>
113	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
114	
115	const basePremiumForSameTypeItems = (type: string, count: number): number =>
116	  isComponentBlock(type, count) ? COMPONENT_BLOCK_BASE : basePremiumOf(type) * count;
117	
118	const itemsBasePremium = (items: Item[]): number =>
119	  sumBy(countItemsByType(items), ([type, count]) => basePremiumForSameTypeItems(type, count));
120	
121	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
122	
123	const LOYALTY_YEARS_THRESHOLD = 2;
124	const LOYALTY_DISCOUNT_RATE = 0.2;
125	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
126	
127	interface QuoteContext {
128	  customer: Customer;
129	  isFollowUp: boolean;
130	}
131	
132	const isLoyalCustomer = ({ customer }: QuoteContext): boolean =>
133	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
134	
135	const isFollowUpQuote = ({ isFollowUp }: QuoteContext): boolean => isFollowUp;
136	
137	const DISCOUNT_RATES: ReadonlyArray<{ applies: (ctx: QuoteContext) => boolean; rate: number }> = [
138	  { applies: isLoyalCustomer, rate: LOYALTY_DISCOUNT_RATE },
139	  { applies: isFollowUpQuote, rate: FOLLOW_UP_DISCOUNT_RATE },
140	];
141	
142	const totalDiscount = (base: number, context: QuoteContext): number =>
143	  base * sumBy(DISCOUNT_RATES, ({ applies, rate }) => (applies(context) ? rate : 0));
144	
145	const quotePremium = ({ items }: QuoteStep, context: QuoteContext): number => {
146	  const base = itemsBasePremium(items);
147	  const premiumBeforeFee =
148	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - totalDiscount(base, context);
149	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
150	};
151	
152	interface Policy {
153	  items: Item[];
154	  remainingCap: number;
155	}
156	
157	const createPolicy = (step: QuoteStep): Policy => ({
158	  items: step.items,
159	  remainingCap: sumBy(step.items, (item) => insuranceValueOf(item.type)) * CAP_MULTIPLIER,
160	});
161	
162	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
163	const FULL_REIMBURSEMENT_RATE = 1;
164	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
165	
166	const hasHighEnchantmentForClaim = (item: Item): boolean =>
167	  enchantmentOf(item) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
168	
169	const reimbursementRate = (item: Item): number =>
170	  hasHighEnchantmentForClaim(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
171	
172	const damagePayout = (damage: Damage, item: Item): number =>
173	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
174	
175	const findItem = (policy: Policy, itemType: string): Item =>
176	  policy.items.find((item) => item.type === itemType)!;
177	
178	const calculatePayout = (damages: Damage[], policy: Policy): number => {
179	  const rawPayout = sumBy(damages, (damage) => damagePayout(damage, findItem(policy, damage.itemType)));
180	  return roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
181	};
182	
183	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
184	  const policy = policies.get(step.policy)!;
185	  const payout = calculatePayout(step.incident.damages, policy);
186	  policy.remainingCap -= payout;
187	  return { payout, remainingCap: policy.remainingCap };
188	};
189	
190	const processQuote = (
191	  step: QuoteStep,
192	  customer: Customer,
193	  policies: Map<number, Policy>,
194	): QuoteResult => {
195	  const context: QuoteContext = { customer, isFollowUp: policies.size > 0 };
196	  policies.set(policies.size, createPolicy(step));
197	  return { premium: quotePremium(step, context) };
198	};
199	
200	const processStep = (
201	  step: Step,
202	  customer: Customer,
203	  policies: Map<number, Policy>,
204	): StepResult =>
205	  step.op === "quote"
206	    ? processQuote(step, customer, policies)
207	    : processClaim(step, policies);
208	
209	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
210	  const policies = new Map<number, Policy>();
211	  const results = steps.map((step) => processStep(step, customer, policies));
212	  return { results };
213	};
